import{_ as n,a0 as l,w as d,s,I as p,x as r,a1 as e,A as i,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"如何在 Cacti 中合併兩幅圖片 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Cacti 中合併兩幅圖片 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Cacti 中合併兩幅圖片 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Cacti 中合併兩幅圖片 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150615 How to combine two graphs on Cacti","title":"如何在 Cacti 中合併兩幅圖片","tag":"201507","desc":""},"relativePath":"201507/20150615 How to combine two graphs on Cacti.md","filePath":"[post].md"}'),c={name:"201507/20150615 How to combine two graphs on Cacti.md"};function h(f,t,m,R,C,u){const a=l("Link");return d(),s("div",null,[t[18]||(t[18]=p("h1",{id:"如何在-cacti-中合併兩幅圖片",tabindex:"-1"},[r("如何在 Cacti 中合併兩幅圖片 "),p("a",{class:"header-anchor",href:"#如何在-cacti-中合併兩幅圖片","aria-label":"Permalink to “如何在 Cacti 中合併兩幅圖片”"},"​")],-1)),p("p",null,[e(a,{href:"https://linux.cn/article-5746-1.html"},{default:i(()=>[...t[0]||(t[0]=[r("Cacti",-1)])]),_:1}),t[1]||(t[1]=r(" 是一個很棒的開源網絡監視系統，它廣泛使用於圖形化地展示網絡元素，例如帶寬、存儲、處理器和內存使用。使用它的基於Web 的界面，你可以輕鬆地創建和組織各種圖表。然而，它默認並沒有提供一些高級功能，例如合併圖片、使用多個來源創建聚合圖形、遷移 Cacti 到另一台服務器。使用 Cacti 的這些功能你還需要一些經驗。在該教程中，我們會看到如何在將兩幅 Cacti 圖片合併為一幅。",-1))]),t[19]||(t[19]=o('<p>看看這個例子。在過去的 6 個月中，客户端 A 連接到了交換機 A 的端口 5。端口 5 發生了錯誤，因此客户端遷移到了端口 6。由於 Cacti 為每個接口/元素使用不同的圖，客户端的帶寬歷史會分成端口 5 和端口 6。結果是對於一個客户端我們有兩幅圖片 - 一幅是 6 個月的舊數據，另一幅保存了後續的數據。</p><p>在這種情況下，我們實際上可以合併兩幅圖片將舊數據加到新的圖中，使得用一個單獨的圖為一個用户保存歷史的和新數據。本教程將會解釋如何做到這一點。</p><p>Cacti 將每幅圖片的數據保存在它自己的 RRD（round robin database，循環資料庫）文件中。當請求一幅圖片時，根據保存在對應 RRD 文件中的值生成圖。在 Ubuntu/Debian 系統中，RRD 文件保存在 <code>/var/lib/cacti/rra</code>，在 CentOS/RHEL 系統中則是 <code>/var/www/cacti/rra</code>。</p><p>合併圖片背後的思想是更改這些 RRD 文件使得舊 RRD 文件中的值能追加到新的 RRD 文件中。</p><h3 id="情景" tabindex="-1">情景 <a class="header-anchor" href="#情景" aria-label="Permalink to “情景”">​</a></h3><p>一個客户端的服務在 eth0 上運行了超過一年。由於硬件損壞，客户端遷移到了另一台服務器的 eth1 接口。我們想展示新接口的帶寬，同時保留超過一年的歷史數據。該客户端希望只在一幅圖中顯示。</p><h3 id="確定圖的-rrd-文件" tabindex="-1">確定圖的 RRD 文件 <a class="header-anchor" href="#確定圖的-rrd-文件" aria-label="Permalink to “確定圖的 RRD 文件”">​</a></h3><p>圖合併的首個步驟是確定與圖相關聯的 RRD 文件。我們可以通過以調試模式打開圖檢查文件。要做到這點，在 Cacti 的菜單中： 控制台 &gt; 管理圖 &gt; 選擇圖 &gt; 打開圖調試模式。</p><h4 id="舊圖" tabindex="-1">舊圖： <a class="header-anchor" href="#舊圖" aria-label="Permalink to “舊圖：”">​</a></h4><p><img src="https://farm4.staticflickr.com/3853/18795518096_f50a78d082_c.jpg" alt=""></p><h4 id="新圖" tabindex="-1">新圖： <a class="header-anchor" href="#新圖" aria-label="Permalink to “新圖：”">​</a></h4><p><img src="https://farm4.staticflickr.com/3674/18634036918_5c4118c4b9_c.jpg" alt=""></p><p>從樣例輸出（基於 Debian 系統）中，我們可以確定兩幅圖片的 RRD 文件：</p><ul><li><strong>舊圖</strong>： /var/lib/cacti/rra/old_graph_traffic_in_8.rrd</li><li><strong>新圖</strong>： /var/lib/cacti/rra/new_graph_traffic_in_10.rrd</li></ul><h3 id="準備腳本" tabindex="-1">準備腳本 <a class="header-anchor" href="#準備腳本" aria-label="Permalink to “準備腳本”">​</a></h3>',15)),p("p",null,[t[3]||(t[3]=r("我們會用一個 ",-1)),e(a,{href:"http://svn.cacti.net/viewvc/developers/thewitness/rrdsplice/rrdsplice.php"},{default:i(()=>[...t[2]||(t[2]=[r("RRD 剪接腳本",-1)])]),_:1}),t[4]||(t[4]=r(" 來合併兩個 RRD 文件。下載該 PHP 腳本，並安裝到 /var/lib/cacti/rra/rrdsplice.php (Debian/Ubuntu 系統) 或 /var/www/cacti/rra/rrdsplice.php (CentOS/RHEL 系統)。",-1))]),t[20]||(t[20]=o(`<p>下一步，確認 Apache 用户擁有該文件。</p><p>在 Debian 或 Ubuntu 系統中，運行下面的命令：</p><pre><code># chown www-data:www-data rrdsplice.php
</code></pre><p>並更新 rrdsplice.php。查找下面的行：</p><pre><code>chown($finrrd, &quot;apache&quot;);
</code></pre><p>用下面的語句替換：</p><pre><code>chown($finrrd, &quot;www-data&quot;);
</code></pre><p>在 CentOS 或 RHEL 系統中，運行下面的命令即可：</p><pre><code># chown apache:apache rrdsplice.php
</code></pre><h3 id="合併兩幅圖" tabindex="-1">合併兩幅圖 <a class="header-anchor" href="#合併兩幅圖" aria-label="Permalink to “合併兩幅圖”">​</a></h3><p>通過不帶任何參數運行該腳本可以獲得腳本的使用語法。</p><pre><code># cd /path/to/rrdsplice.php
# php rrdsplice.php 
</code></pre><hr><pre><code>USAGE: rrdsplice.php --oldrrd=file --newrrd=file --finrrd=file
</code></pre><p>現在我們準備好合併兩個 RRD 文件了。只需要指定舊 RRD 文件和新 RRD 文件的名稱。我們會將合併後的結果重寫到新 RRD 文件中。</p><pre><code># php rrdsplice.php --oldrrd=old_graph_traffic_in_8.rrd --newrrd=new_graph_traffic_in_10.rrd --finrrd=new_graph_traffic_in_10.rrd 
</code></pre><p>現在舊 RRD 文件中的數據已經追加到了新 RRD 文件中。Cacti 會將任何新數據寫到新 RRD 文件中。如果我們點擊圖，我們可以發現也已經添加了舊圖的周、月、年記錄。下面圖表中的第二幅圖顯示了舊圖的週記錄。</p><p><img src="https://farm6.staticflickr.com/5493/18821787015_6730164068_b.jpg" alt=""></p><p>總之，該教程顯示瞭如何簡單地將兩幅 Cacti 圖片合併為一幅。當服務遷移到另一個設備/接口，我們希望只處理一幅圖片而不是兩幅時，這個小技巧非常有用。該腳本非常方便，因為它可以不管源設備是不是相同都可以合併圖片，例如 Cisco 1800 路由器和 Cisco 2960 交換機。</p><p>希望這些能對你有所幫助。</p><hr>`,21)),p("p",null,[t[6]||(t[6]=r("via: ",-1)),e(a,{href:"http://xmodulo.com/combine-two-graphs-cacti.html"},{default:i(()=>[...t[5]||(t[5]=[r("http://xmodulo.com/combine-two-graphs-cacti.html",-1)])]),_:1})]),p("p",null,[t[10]||(t[10]=r("作者：",-1)),e(a,{href:"http://xmodulo.com/author/sarmed"},{default:i(()=>[...t[7]||(t[7]=[r("Sarmed Rahman",-1)])]),_:1}),t[11]||(t[11]=r(" 譯者：",-1)),e(a,{href:"https://github.com/ictlyh"},{default:i(()=>[...t[8]||(t[8]=[r("ictlyh",-1)])]),_:1}),t[12]||(t[12]=r(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...t[9]||(t[9]=[r("wxy",-1)])]),_:1})]),p("p",null,[t[15]||(t[15]=r("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[r("LCTT",-1)])]),_:1}),t[16]||(t[16]=r(" 原創翻譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[r("Linux中國",-1)])]),_:1}),t[17]||(t[17]=r(" 榮譽推出",-1))])])}const g=n(c,[["render",h]]);export{_ as __pageData,g as default};
